# Triplet scheme colors/labels: scheme is a property of the (img2, img3) delta pair
SCHEME_COLORS = ["#1f77b4", "#2ca02c", "#ff7f0e", "#888888"]  # time-time, pitch-pitch, orthogonal, other
SCHEME_LABELS = ["time shift (both)", "pitch shift (both)", "time + pitch (orthogonal)", "other"]

def delta_scheme(deltas, n_groups=None):
    "Map deltas → scheme index: 0=time-time, 1=pitch-pitch, 2=orthogonal, 3=other"
    d = deltas.cpu().numpy() if hasattr(deltas, "cpu") else np.asarray(deltas)
    if d.ndim == 3:              # (bs, 2, 2): batch of [d2, d3] pairs
        d2, d3 = d[:, 0], d[:, 1]
        h = d2 * d3
        return np.where(h.sum(-1)==0, 2, np.where(h[:,1]==0, 0, np.where(h[:,0]==0, 1, 3)))
    if n_groups is not None:    # (3*N, 2): flat [anchors, img2s, img3s]
        d2, d3 = d[n_groups:2*n_groups], d[2*n_groups:3*n_groups]
        h = d2 * d3
        scheme = np.where(h.sum(-1)==0, 2, np.where(h[:,1]==0, 0, np.where(h[:,0]==0, 1, 3)))
        return np.concatenate([scheme, scheme, scheme])
    return (d[:,0]!=0).astype(int) + 2*(d[:,1]!=0).astype(int)  # per-point fallback


